async () => {
window.__ev=[]; for (const n of ['conversation_closed:agent_0x99','conversation_closed:robert_vance_phone','global_variable_changed:mission_complete','global_variable_changed:anomaly_detected','global_variable_changed:anomaly_call_heard','phone_call_answered:agent_0x99','phone_call_declined:agent_0x99','phone_call_missed:agent_0x99','phone_call_answered:robert_vance_phone','objective_task_completed:call_in_after_sweep','game_loaded']) window.eventDispatcher.on(n, (d)=>window.__ev.push(n+'@'+Math.round(performance.now()/100)/10+(d&&d.callback?' callback':'')+(d&&d.reload?' reload':''))); return true;

}

